import BytesMacros

// The zip central directory parsed with records declared once and generated by `BytesMacros`: the 46-byte
// header and each extra field's header as `@BinaryRecord`s, the extended timestamp's flags as `@BitFields`.
// The same fields as the hand-written parsers, so the same checksum.

/// A central directory entry's fixed header (APPNOTE 4.3.12).
@BinaryRecord(.littleEndian)
struct CentralDirectoryHeader {
    @Field(Byte4.self, expecting: 0x0201_4B50) var signature: UInt32
    @Field(Byte2.self) var versionMadeBy: UInt16
    @Field(Byte2.self) var versionNeeded: UInt16
    @Field(Byte2.self) var flags: UInt16
    @Field(Byte2.self) var method: UInt16
    @Field(Byte2.self) var time: UInt16
    @Field(Byte2.self) var date: UInt16
    @Field(Byte4.self) var crc32: UInt32
    @Field(Byte4.self) var compressedSize: UInt32
    @Field(Byte4.self) var uncompressedSize: UInt32
    @Field(Byte2.self) var nameLength: Int
    @Field(Byte2.self) var extraLength: Int
    @Field(Byte2.self) var commentLength: Int
    @Field(Byte2.self) var diskNumberStart: UInt16
    @Field(Byte2.self) var internalAttributes: UInt16
    @Field(Byte4.self) var externalAttributes: UInt32
    @Field(Byte4.self) var localHeaderOffset: UInt32
}

/// An extra field's header: its tag and its data's length.
@BinaryRecord(.littleEndian)
struct ExtraFieldHeader {
    @Field(Byte2.self) var id: UInt16
    @Field(Byte2.self) var size: Int
}

/// The extended timestamp field's flags: which times follow.
@BitFields(Byte.self)
struct ExtendedTimestampFlags {
    @Flag(bit: 0) var modification: Bool
    @Flag(bit: 1) var access: Bool
    @Flag(bit: 2) var creation: Bool
}

public extension CentralDirectory {
    /// Parses a central directory with records generated by `@BinaryRecord` and `@BitFields`.
    ///
    /// - Parameter span: The directory.
    /// - Returns: The sum of the fields read, as ``parseWithBytes(_:)``.
    /// - Throws: As ``parseWithBytes(_:)``.
    static func parseWithBytesMacros(_ span: RawSpan) throws -> UInt64 {
        var reader = LittleEndianBytesReader(span)
        var fields = Fields()
        while !reader.isAtEnd {
            let header = try reader.read(CentralDirectoryHeader.self)
            fields.add(header.versionMadeBy)
            fields.add(header.flags)
            fields.add(header.method)
            fields.add(header.time)
            fields.add(header.date)
            fields.add(header.crc32)
            fields.add(header.compressedSize)
            fields.add(header.uncompressedSize)
            fields.add(header.externalAttributes)
            fields.add(header.localHeaderOffset)
            try fields.add(reader.read(byteCount: header.nameLength).byteCount)
            var extra = try reader.readSection(byteCount: header.extraLength)
            try reader.skip(byteCount: header.commentLength)
            while extra.remainingByteCount >= ExtraFieldHeader.byteCount {
                let fieldHeader = try extra.read(ExtraFieldHeader.self)
                var field = try extra.readSection(byteCount: fieldHeader.size)
                if fieldHeader.id == 0x5455, fieldHeader.size >= 5, try field.read(ExtendedTimestampFlags.self).modification {
                    try fields.add(field.read(Int32.self, asSigned: Byte4.self))
                }
            }
        }
        return fields.checksum
    }
}
